-- 3. Genuine Welfare Schemes & Samachar Content
insert into public.content (id, type, title_en, title_hi, desc_en, desc_hi, badge, link, tag, published_at)
values
  ('s-eshram', 'scheme', 'e-Shram Accident Insurance (₹2 Lakh)', 'ई-श्रम दुर्घटना बीमा (₹2 लाख सुरक्षा)', 'Free accidental death and permanent disability coverage of ₹2,00,000 for registered construction workers.', 'पंजीकृत निर्माण श्रमिकों के लिए ₹2,00,000 का निःशुल्क दुर्घटना बीमा एवं पेंशन सहायता।', 'Government of India', 'https://eshram.gov.in', 'Welfare', '2026-09-01'),
  ('s-bocw', 'scheme', 'BOCW Tool-kit Grant (₹15,000)', 'BOCW टूल-किट अनुदान (₹15,000 सहायता)', 'Financial assistance to purchase modern tools for Masons, Electricians, Plumbers, and Carpenters.', 'मिस्त्री, इलेक्ट्रीशियन, प्लंबर व बढ़ई को आधुनिक औजार खरीदने के लिए ₹15,000 की प्रत्यक्ष सहायता।', 'State Welfare Board', 'https://bocw.gov.in', 'Welfare', '2026-09-01'),
  ('s-pmawas', 'scheme', 'PM Awas Yojana Subsidy', 'प्रधानमंत्री आवास योजना (₹1.20 लाख सहायता)', 'Direct financial grant for rural and semi-urban workers to construct pucca houses.', 'पक्का मकान बनाने के लिए सरकार द्वारा ₹1,20,000 से ₹2,50,000 तक का प्रत्यक्ष अनुदान।', 'MoHUA', 'https://pmaymis.gov.in', 'Welfare', '2026-09-01'),
  ('s-ayushman', 'scheme', 'Ayushman Bharat PM-JAY (₹5 Lakh Free Treatment)', 'आयुष्मान भारत योजना (₹5 लाख तक मुफ़्त इलाज)', 'Cashless health coverage up to ₹5 Lakh per year for the entire worker family at empanelled hospitals.', 'पूरे परिवार के लिए देश के किसी भी अस्पताल में ₹5 लाख तक का कैशलेस मुफ़्त इलाज।', 'NHA Health', 'https://pmjay.gov.in', 'Welfare', '2026-09-01'),
  ('n-1', 'news', 'UP Government hikes minimum daily wage for Raj Mistri to ₹850', 'उत्तर प्रदेश सरकार ने कुशल मिस्त्री की न्यूनतम दैनिक मजदूरी बढ़ाई', 'UP Government hikes minimum daily wage for Raj Mistri to ₹850', 'उत्तर प्रदेश सरकार ने कुशल मिस्त्री की न्यूनतम दैनिक मजदूरी बढ़ाई', 'Wages', '#', 'Wages', 'Today, 10:30 AM'),
  ('n-2', 'news', 'Nirmaan Escrow Vault crosses ₹5 Crore in direct instant worker payouts', 'निर्माण एस्क्रो वॉल्ट ने ₹5 करोड़ का सीधा मज़दूर भुगतान पूरा किया', 'Nirmaan Escrow Vault crosses ₹5 Crore in direct instant worker payouts', 'निर्माण एस्क्रो वॉल्ट ने ₹5 करोड़ का सीधा मज़दूर भुगतान पूरा किया', 'Milestone', '#', 'Milestone', 'Yesterday'),
  ('n-3', 'news', 'Free health checkup camp for Karigars in Noida Sector 62 this Sunday', 'इस रविवार नोएडा सेक्टर 62 में निर्माण कारीगरों के लिए मुफ़्त स्वास्थ्य शिविर', 'Free health checkup camp for Karigars in Noida Sector 62 this Sunday', 'इस रविवार नोएडा सेक्टर 62 में निर्माण कारीगरों के लिए मुफ़्त स्वास्थ्य शिविर', 'Welfare', '#', 'Welfare', '28 Sep')
on conflict (id) do update set
  title_en = excluded.title_en,
  title_hi = excluded.title_hi,
  desc_en = excluded.desc_en,
  desc_hi = excluded.desc_hi,
  badge = excluded.badge,
  link = excluded.link;
